/**
 * @component modal
 * @selector .pfx-modal
 * @summary A dialog surface (works on a native <dialog>); header/body/footer parts.
 * @remarks On a native <dialog>, `showModal()` puts the modal in the top layer and its `::backdrop` becomes the mask, so no z-index is needed. An `<img>` alone in `.body` goes full-bleed.
 * @element dialog
 * @modifier -size-sm — A narrow modal.
 * @modifier -size-lg — A wide modal.
 * @modifier -size-auto — Sized to content.
 * @modifier -size-fullscreen — Edge-to-edge.
 * @modifier -density-compact — Tighter part padding. @affects modal.header @affects modal.body @affects modal.footer — Tightens each part's padding.
 * @modifier -color-inverse — On-dark chrome (pairs with a media body). @affects modal.header @affects modal.body @affects modal.footer — Recolours each part for the on-dark look.
 * @modifier -blur — Blur the backdrop behind the modal.
 * @modifier -overflow-fit — Constrain to the viewport and scroll the body. @affects modal.body — Scrolls the body when the modal is capped to the viewport.
 * @remarks See the `modal.header`, `modal.body`, and `modal.footer` members for the individual parts.
 * @pseudo ::backdrop — Dims the page behind the dialog as its mask, and frosts it under `-blur`.
 * @accessibility Open the native `<dialog>` with `showModal()` for modal semantics and Esc-to-close, and name it with `aria-labelledby` pointing at the `.header`.
 * @compat Styles a native <dialog> and its `::backdrop`; the top-layer rendering and backdrop styling need a browser that supports the dialog element.
 * @example -canvas-rce
 * <dialog class="pfx-modal -size-sm" id="modal-sm">
 *   <div class="header"><strong>Small</strong></div>
 *   <div class="body"><code>-size-sm</code> — a narrow modal.</div>
 *   <div class="footer">
 *     <button class="pfx-button">Close</button>
 *   </div>
 * </dialog>
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" command="--show" commandfor="account-dialog" data-a11y-trigger>Open account details</button>
 * <dialog class="pfx-modal -size-sm" id="account-dialog" aria-labelledby="account-dialog-title" data-a11y-root>
 *   <div class="header" id="account-dialog-title"><strong>Account details</strong></div>
 *   <div class="body">Review your account information.</div>
 *   <div class="footer"><button class="pfx-button" command="--close" commandfor="account-dialog">Close</button></div>
 * </dialog>
 * ```
 * @example -docs
 * <dialog class="pfx-modal -size-lg" aria-labelledby="details-title">
 *   <div class="header" id="details-title"><strong>More information</strong></div>
 *   <div class="body">This example shows the large modal surface.</div>
 * </dialog>
 * @structure
 * .pfx-modal {
 *   .header {}
 *   .body {}
 *   .footer {}
 * }
 * @related tray — A tray is the same dismissible overlay pattern, anchored to a screen edge.
 * @demo self:modal
 */
@scope (.pfx-modal) {
  & {
    max-width: var(--instui-component-modal-medium-max-width);
    background: var(--instui-component-modal-background-color);
    color: var(--instui-component-modal-text-color);
    border: var(--instui-component-modal-border-width) solid
      var(--instui-component-modal-border-color);
    border-radius: var(--instui-component-modal-border-radius);
    font-family: var(--instui-component-modal-font-family);
    overflow: hidden;
    /* Modals float above the page; the elevation tokens are defined at the top of components.css. */
    box-shadow: var(--instui-elevation-topmost);
  }

  /* On a native <dialog>, drop the UA padding and centre it; `showModal()` puts it in the top layer, so
     no z-index is needed. The dialog's ::backdrop IS the modal's mask — dim it with the Mask token; the
     optional -blur modifier frosts it (mirrors .pfx-mask.-blur). */
  &[is="dialog"],
  dialog& {
    margin: auto;
    padding: 0;
  }

  &[is="dialog"]::backdrop,
  dialog&::backdrop {
    background: var(--instui-component-mask-background-color);
  }

  &[is="dialog"].-blur::backdrop,
  dialog&.-blur::backdrop {
    backdrop-filter: blur(0.5rem);
  }

  &.-size-sm {
    max-width: var(--instui-component-modal-small-max-width);
  }

  &.-size-lg {
    max-width: var(--instui-component-modal-large-max-width);
  }

  &.-size-auto {
    max-width: none;
    min-width: var(--instui-component-modal-auto-min-width);
  }

