/**
 * @component tooltip
 * @selector .pfx-tooltip
 * @summary A CSS hover and focus tooltip bubble, positionable on any side.
 * @remarks Toggling is pure CSS (`:hover`/`:focus-within`), so the bubble only reaches keyboard users through a focusable trigger; unlike `popover`, it isn't dismissible or click-triggered.
 * @modifier -icon-* — Render a trigger glyph icon next to the tooltip bubble.
 * @part .tip — The bubble; `-placement-*` sets its side.
 * @a11y Point the trigger at the bubble with aria-describedby and give the bubble role="tooltip".
 * @example -canvas-rce
 * ```html
 * <span class="pfx-tooltip" aria-describedby="tt-1">
 *   <span class="pfx-icon -icon-info"></span>
 *   <span class="tip" id="tt-1" role="tooltip">Default placement is top</span>
 * </span>
 * ```
 * @example -automatica11y
 * ```html
 * <span class="pfx-tooltip">
 *   <button class="pfx-button" type="button" aria-describedby="help-tip" data-a11y-trigger>Help</button>
 *   <span class="tip" id="help-tip" role="tooltip" data-a11y-root>Find answers to common questions.</span>
 * </span>
 * ```
 * @example -docs
 * ```html
 * <span class="pfx-tooltip">
 *   <button class="pfx-button" type="button" aria-describedby="placement-tip">Placement</button>
 *   <span class="tip -placement-bottom" id="placement-tip" role="tooltip">This tooltip appears below.</span>
 * </span>
 * ```
 * @structure
 * .pfx-tooltip {
 *   [class*="-icon-"]:optional {}
 *   .tip {}
 * }
 * @related popover — The larger, click-triggered anchored surface.
 * @related context-view — A related anchored surface with a pointer.
 */
@scope (.pfx-tooltip) {
  :scope {
    position: relative;
    display: inline-flex;

    > :is([class^="-icon-"], [class*=" -icon-"]) {
      line-height: 1;
    }

    > .tip {
      position: absolute;
      inline-size: max-content;
      z-index: 1;
      inset-block-end: 100%;
      inset-inline-start: 50%;
      transform: translateX(-50%);
      margin-block-end: var(--instui-spacing-space-xs);
      padding: var(--instui-component-tooltip-padding);
      background: var(--instui-color-background-inverse);
      color: var(--instui-color-text-inverse);
      border-radius: var(--instui-border-radius-sm);
      font-family: var(--instui-component-tooltip-font-family);
      font-size: var(--instui-component-tooltip-font-size);
      font-weight: var(--instui-component-tooltip-font-weight);
      white-space: nowrap;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 0.15s ease;

      /* translateX is physical while the inset is logical, so RTL needs the opposite sign to stay centered. */
      &:dir(rtl) {
        transform: translateX(50%);
      }

