import { createRequire } from 'node:module';
import { realpathSync } from 'node:fs';
const require = createRequire(realpathSync(createRequire(process.cwd() + '/formats/components/package.json').resolve('automatica11y/package.json')));
const { chromium } = require('playwright-core');
const browser = await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try {
 for (const record of ['modal','popover','tooltip','toggle-details','tree-browser']) {
  const page = await browser.newPage();
  const errors = []; page.on('pageerror', error => errors.push(error.message));
  await page.goto(`file://${process.cwd()}/a11y-report/2026-10-27T15-56-24.688Z/pages/${record}-1-rebrand-light.html`);
  await page.waitForTimeout(200);
  const state = await page.evaluate(() => ({dialog:document.querySelector('dialog')?.matches(':modal'),popover:document.querySelector('.instui-popover') && getComputedStyle(document.querySelector('.instui-popover')).visibility,tooltip:document.querySelector('.tip') && getComputedStyle(document.querySelector('.tip')).visibility,closedDetails:document.querySelectorAll('details:not([open])').length}));
  console.log(record, JSON.stringify({state,errors}));
  if (errors.length || state.closedDetails || (record==='modal' && !state.dialog) || (record==='popover' && state.popover!=='visible') || (record==='tooltip' && state.tooltip!=='visible')) throw new Error('Expanded surface verification failed');
  await page.close();
 }
} finally { await browser.close(); }
