import { createRequire } from 'node:module';
import { cpSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { tmpdir } from 'node:os';
import { collectExamples, expandCases, renderPage } from './formats/components/scripts/audit-accessibility.ts';
import { COMPONENTS } from './formats/components/src/components/index.ts';
const require = createRequire(process.cwd() + '/formats/components/package.json');
const { parseCssDocs } = await import(require.resolve('@cssdoc/core'));
const toolRoot = dirname(realpathSync(require.resolve('automatica11y/package.json')));
const { serveStatic } = await import(join(toolRoot,'src/harness/static-serve.js'));
const { chromium } = createRequire(join(toolRoot,'package.json'))('playwright-core');
const root = mkdtempSync(join(tmpdir(),'pantoken-http-check-'));
cpSync('a11y-report/2026-10-27T16-18-15.847Z/pages/assets',join(root,'assets'),{recursive:true});
const selected = COMPONENTS.filter(c=>['button','modal','tooltip','toggle-details','popover'].includes(c.name));
const examples = collectExamples(selected.flatMap(c=>parseCssDocs(c.rules('instui-'))),selected.map(c=>c.name));
const cases = expandCases(examples).filter(c=>c.record==='button'||(c.theme==='rebrand'&&c.scheme==='light'));
for(const c of cases) writeFileSync(join(root,`${c.id}.html`),renderPage(c));
const server = await serveStatic(root);
const browser = await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try {
 for(const c of cases){
  const page = await browser.newPage(); const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  page.on('response',r=>{if(r.status()>=400) errors.push(`${r.status()} ${r.url()}`)});
  await page.goto(`${server.origin}/${c.id}.html`,{waitUntil:'networkidle'});
  await page.evaluate(()=>document.fonts.ready); await page.waitForTimeout(200);
  const state=await page.evaluate(()=>({background:document.querySelector('.instui-button')&&getComputedStyle(document.querySelector('.instui-button')).backgroundColor,scheme:getComputedStyle(document.documentElement).colorScheme,modal:document.querySelector('dialog')?.matches(':modal'),tooltip:document.querySelector('.tip')&&getComputedStyle(document.querySelector('.tip')).visibility,closedDetails:document.querySelectorAll('details:not([open])').length}));
  if(errors.length||state.closedDetails||(c.record==='button'&&(!state.background||state.background==='rgba(0, 0, 0, 0)'))||state.scheme!==c.scheme||(c.record==='modal'&&!state.modal)||(c.record==='tooltip'&&state.tooltip!=='visible')) throw new Error(JSON.stringify({id:c.id,state,errors}));
  console.log(c.id,JSON.stringify(state),'no HTTP/JS errors'); await page.close();
 }
} finally { await browser.close(); await server.close(); rmSync(root,{recursive:true,force:true}); }
