import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
const out=resolve('a11y-report/2026-10-27T17-25-10.017Z-npm-verification');
const {cases,evidence}=JSON.parse(readFileSync(`${out}/coverage.json`));
if(cases.length!==456||evidence.length!==15||evidence.some(e=>e.error||e.expected.length!==e.completed.length)) throw new Error('Incomplete combined inventory');
let pages=0,npm=0;
for(const batch of evidence){
 const results=JSON.parse(readFileSync(resolve(out,batch.directory,'results.json')));
 if(results.targets.length!==batch.expected.length) throw new Error(`Missing targets: ${batch.directory}`);
 for(const target of results.targets){
  const [name,archetype]=Object.entries(target.archetypes)[0];
  const isNpm=batch.directory.startsWith('npm-');
  if(target.status!=='ran'||archetype.status!=='ran'||(isNpm&&archetype.fixture.source!=='authored')) throw new Error(`Invalid provenance: ${target.id}`);
  for(const config of archetype.configs){
   const tiers=config.tiers;
   if(['axe','ibm'].some(engine=>tiers.rules.engines[engine].status!=='ran')) throw new Error(`Missing engine: ${target.id}`);
   for(const tier of isNpm?['rules','interactions','computed','conditions','vsr']:['rules','conditions','vsr']) if(tiers[tier]?.status!=='ran') throw new Error(`Missing ${tier}: ${target.id}`);
   if(!tiers.vsr.simulated) throw new Error(`Unmarked simulated VSR: ${target.id}`);
  }
  if(isNpm) npm++; else pages++;
 }
}
if(pages!==456||npm!==54) throw new Error('Wrong coverage counts');
console.log({pageCases:pages,authoredNpmCases:npm,completeCases:pages+npm,reportBatches:evidence.length,gaps:evidence.reduce((n,e)=>n+e.gaps,0)});
