import {readFileSync} from 'node:fs'; import {resolve} from 'node:path';
const out=resolve('a11y-report/2026-10-27T17-25-10.017Z-npm-verification');const {evidence}=JSON.parse(readFileSync(`${out}/coverage.json`));
const groups=new Map();const totals={axe:{violations:0,review:0},ibm:{violations:0,review:0},interactions:0,computed:0,conditions:0,vsr:0,coverage:0};
function add(kind,key,detail,id,extra={}){const k=`${kind}|${key}`;let g=groups.get(k);if(!g){g={kind,key,count:0,targets:new Set(),details:new Set(),...extra};groups.set(k,g)}g.count++;g.targets.add(id);if(g.details.size<3)g.details.add(detail)}
for(const batch of evidence){const r=JSON.parse(readFileSync(resolve(out,batch.directory,'results.json')));for(const gap of r.outcome.coverage??[]){totals.coverage++; add('coverage',gap.split('/').slice(-2).join('/'),gap,gap.split('/')[0]);}for(const t of r.targets){for(const [a,ar] of Object.entries(t.archetypes))for(const c of ar.configs){for(const [engine,result] of Object.entries(c.tiers.rules?.engines??{})){totals[engine].violations+=result.violations.length;totals[engine].review+=result.incomplete.length;for(const f of result.violations)add(engine,f.ruleId,f.help,t.id,{severity:f.impact??f.toolkitLevel,selector:f.nodes[0]?.selector});for(const f of result.incomplete)add(`${engine}-review`,f.ruleId,f.help,t.id,{severity:f.impact??f.toolkitLevel});}for(const tier of ['interactions','computed','conditions'])for(const check of c.tiers[tier]?.checks??[])if(check.result!=='pass'&&check.result!=='not-applicable'){totals[tier]++;add(tier,check.name,check.detail,t.id,{result:check.result});}for(const flag of c.tiers.vsr?.flags??[]){totals.vsr++;add('vsr',flag.name??flag.kind??JSON.stringify(flag),JSON.stringify(flag),t.id)}}}}
console.log('TOTALS (engine result entries, not affected nodes):',JSON.stringify(totals));
for(const g of groups.values())console.log(JSON.stringify({...g,targets:[...g.targets],details:[...g.details]}));
