/**
 * @component menu
 * @selector .pfx-menu
 * @summary A dropdown surface of items, groups, and separators.
 * @remarks Compose entries as `.item` (see the `menu.item` member), label a section with `.group` (see `menu.group`), and divide sections with `.separator` (see `menu.separator`).
 * @structure
 * .pfx-menu {
 *   .group:optional {}
 *   .item:many {}
 *   .separator:optional {}
 * }
 * @example -canvas-rce -nocard
 * ```html
 * <div class="pfx-menu">
 *   <div class="group">Actions</div>
 *   <div class="item">Edit</div>
 *   <div class="item -active">Duplicate</div>
 *   <div class="separator"></div>
 *   <div class="item">Delete</div>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <button class="pfx-button" popovertarget="actions-menu" data-a11y-trigger>Actions</button>
 * <div class="pfx-menu" id="actions-menu" popover="auto" role="menu" aria-label="Actions" data-a11y-root>
 *   <button class="item" role="menuitem">Edit</button>
 *   <button class="item" role="menuitem">Delete</button>
 * </div>
 * ```
 * @example -docs -nocard
 * ```html
 * <div class="pfx-menu">
 *   <div class="group">View</div>
 *   <div class="item">List</div>
 *   <div class="item -active">Grid</div>
 * </div>
 * ```
 * @related tree-browser — Both present nested, selectable entries.
 * @related simple-select — A select's dropdown reuses this menu surface.
 */
@scope (.pfx-menu) {
  & {
    min-width: var(--instui-component-menu-min-width);
    max-width: var(--instui-component-menu-max-width);
    background: var(--instui-component-menu-item-background);
    border: var(--instui-border-width-sm) solid var(--instui-color-stroke-base);
    border-radius: var(--instui-border-radius-md);
    padding: var(--instui-spacing-space-xs) 0;
  }
}

