/**
 * @component menu.item
 * @memberOf menu
 * @selector .item
 * @summary A menu entry (InstUI `Menu.Item`); add -disabled, -highlighted, or -active/[aria-checked].
 * @modifier -disabled — Muted, non-interactive.
 * @modifier -highlighted — Highlighted background/text (keyboard focus or hover).
 * @modifier -active — Active/checked highlight; same styling as `[aria-checked="true"]`.
 * @part .item-info — Secondary info text within the item.
 * @a11y Mark a checked item with `aria-checked="true"` (same styling as `-active`).
 * @structure
 * @component menu {
 *   .item {
 *     .item-info {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" popovertarget="actions-menu" data-a11y-trigger>Actions</button>
 * <div class="pfx-menu" id="actions-menu" popover="auto" role="menu" aria-label="Actions" data-a11y-root>
 *   <button class="item" role="menuitem">Edit</button>
 *   <button class="item" role="menuitem">Delete</button>
 * </div>
 * ```
 */
@scope (.pfx-menu) {
  :scope {
    > .item {
      display: block;
      padding: var(--instui-component-menu-item-padding-vertical)
        var(--instui-component-menu-item-padding-horizontal);
      color: var(--instui-component-menu-item-label-color);
      font-family: var(--instui-component-menu-item-font-family);
      font-size: var(--instui-component-menu-item-font-size);
      font-weight: var(--instui-component-menu-item-font-weight);
      line-height: var(--instui-component-menu-item-line-height);
      cursor: pointer;
    }

    /* A disabled item (InstUI Menu.Item `disabled`): muted, non-interactive. */
    > .item.-disabled {
      opacity: var(--instui-opacity-disabled);
      pointer-events: none;
      cursor: not-allowed;
    }

    > .item:hover,
    > .item.-highlighted {
      background: var(--instui-component-menu-item-highlighted-background);
      color: var(--instui-component-menu-item-highlighted-label-color);
    }

    > .item.-active,
    > .item[aria-checked="true"] {
      background: var(--instui-component-menu-item-active-background);
      color: var(--instui-component-menu-item-active-label-color);
    }

    > .item.-active:hover,
    > .item[aria-checked="true"]:hover {
      background: var(--instui-component-menu-item-selected-highlighted-background);
    }

    /* Secondary line inside an item (a description or shortcut). */
    .item-info {
      color: var(--instui-component-menu-item-label-info-color);
    }

    > .item:hover .item-info,
    > .item.-highlighted .item-info {
      color: var(--instui-component-menu-item-highlighted-label-info-color);
    }
  }
}

